meta = {"source_of_truth": "OpenZFS (docs/adr/0003)", "code_rev": "b540a2c (HEAD; the working tree has an unfinished file-export merge)",
        "openzfs_rev": "a128b8a (2.4.99); version tables also checked at 2.2.9 / 2.4.0",
        "classification_coverage": open(sys.argv[1]).read(),
        "cost_scale": COST, "reach_scale": REACH,
        "score": "cost of the error the code currently makes x reach"}
for r in L:
    lean = r["current_lean"]
    errs = r["cost_II"] if lean.startswith("II") else r["cost_I"] if lean.startswith("I") else max(r["cost_I"], r["cost_II"], key=COST.get)
    if lean.startswith("II (correct)") or lean == "balanced":
        errs = r["cost_II"]
    r["cost_of_current_error"] = errs
    r["score"] = COST[errs] * REACH[r["reach"].split(" ")[0]]
    r["asymmetry"] = f"I={r['cost_I']}({COST[r['cost_I']]}) vs II={r['cost_II']}({COST[r['cost_II']]})"
L.sort(key=lambda r: -r["score"])
json.dump({"meta": meta, "ledger": L}, open(sys.argv[2], "w"), indent=1)

esc = lambda s: s.replace("|", "\\|").replace("\n", " ")
with open(sys.argv[3], "w") as f:
    f.write("| # | decision | site | predicate | type I (false positive) | type II (false negative) | cost I / II | errs now | default on uncertainty | score |\n")
    f.write("|---|---|---|---|---|---|---|---|---|---|\n")
    for r in L:
        f.write("| " + " | ".join(esc(x) for x in [r["id"], r["decision"], r["site"], r["predicate"], r["typeI"], r["typeII"],
                f"{r['cost_I']} / {r['cost_II']}", r["current_lean"], r["should"], str(r["score"])]) + " |\n")
for r in L:
    print(r["score"], r["id"], r["decision"], "|", r["current_lean"])
